        "core": {
          "ipv4_address": "10.53.0.3"
        }
      },
      "restart": "no",
      "sysctls": {
        "net.ipv4.ip_forward": "1"
      }
    },
    "prometheus": {
      "command": [
        "--config.file=/etc/prometheus/prometheus.yml",
        "--storage.tsdb.path=/prometheus",
        "--storage.tsdb.retention.time=7d",
